import React, { useRef } from "react";

export default function TestimonialGrid() {
  const refs = useRef([]);

  const videos = [
    "/assets/test1.mp4",
    "/assets/test2.mp4"
  ];

  function pauseAll(except) {
    refs.current.forEach((vid, i) => {
      if (!vid) return;
      if (i !== except) vid.pause();
    });
  }

  return (
    <div style={{ padding: "40px", background: "#fafafa" }}>
      <h2>Testimonial Videos</h2>
      <div style={{ display: "flex", gap: "20px", flexWrap: "wrap" }}>
        {videos.map((src, i) => (
          <video
            key={i}
            ref={(el) => (refs.current[i] = el)}
            src={src}
            width="280"
            height="180"
            controls
            playsInline
            preload="metadata"
            onPlay={() => pauseAll(i)}
            style={{ borderRadius: "12px", boxShadow: "0 4px 10px rgba(0,0,0,0.2)" }}
          />
        ))}
      </div>
    </div>
  );
}
